contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _newMin) public payable {
        // Fresh contract precondition: no successful state-changing call yet.
        // Calling Initialized must succeed and mark initialized.
        bool initReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initReverted = true;
        } else {
            initReverted = false;
        }

        // After Initialized succeeds, SetMinSum must revert because intitalized is true.
        bool setMinSumReverted;
        c.SetMinSum(_newMin); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        // General rule: Initialized never reverts, and afterwards SetMinSum always reverts.
        assert(!initReverted && setMinSumReverted);
    }

    receive() external payable {}
}

