// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _newMin) internal {
        bool initReverted;
        try c.Initialized() {
            initReverted = false;
        } catch {
            initReverted = true;
        }
        bool setMinSumReverted;
        try c.SetMinSum(_newMin) {
            setMinSumReverted = false;
        } catch {
            setMinSumReverted = true;
        }
        assertTrue(!initReverted && setMinSumReverted);
    }

    function testFuzz_run(uint256 _newMin) public {
        _run(_newMin);
    }

    receive() external payable {}
}
